package com.fluxisai.proposal;
import java.math.BigDecimal; import java.util.*; import com.fluxisai.catalog.ProfessionalServiceRepository; import com.fluxisai.client.ClientRepository; import com.fluxisai.common.error.ResourceNotFoundException; import com.fluxisai.common.security.CurrentUser; import com.fluxisai.common.web.PageResponse; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ProposalService { private final ProposalRepository proposals; private final ProposalItemRepository items; private final ClientRepository clients; private final ProfessionalServiceRepository services; private final CurrentUser currentUser;
 public ProposalService(ProposalRepository p,ProposalItemRepository i,ClientRepository c,ProfessionalServiceRepository s,CurrentUser u){proposals=p;items=i;clients=c;services=s;currentUser=u;}
 @Transactional public ProposalResponse create(ProposalRequest r){validateClient(r.clientId());validateItems(r.items());return replaceItems(proposals.save(new Proposal(currentUser.id(),r.clientId(),clean(r.title()),optional(r.description()),r.currency(),r.validUntil(),r.status())),r.items());}
 @Transactional(readOnly=true) public ProposalResponse get(UUID id){var p=find(id);return ProposalResponse.from(p,items.findAllByProposalId(p.getId()));}
 @Transactional(readOnly=true) public PageResponse<ProposalResponse> list(Pageable pageable){return PageResponse.from(proposals.findAllByUserId(currentUser.id(),pageable).map(p->ProposalResponse.from(p,items.findAllByProposalId(p.getId()))));}
 @Transactional public ProposalResponse update(UUID id,ProposalRequest r){var p=find(id);validateClient(r.clientId());validateItems(r.items());p.update(r.clientId(),clean(r.title()),optional(r.description()),r.currency(),r.validUntil(),r.status());return replaceItems(p,r.items());}
 @Transactional public void delete(UUID id){proposals.delete(find(id));}
 private ProposalResponse replaceItems(Proposal p,List<ProposalItemRequest> requests){var saved=proposals.save(p);items.deleteAllByProposalId(saved.getId());var created=requests.stream().map(i->new ProposalItem(saved.getId(),i.serviceId(),clean(i.description()),i.quantity(),i.unitPrice())).toList();items.saveAll(created);var total=created.stream().map(ProposalItem::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);saved.totals(total);proposals.save(saved);return ProposalResponse.from(saved,created);}
 private void validateClient(UUID id){if(clients.findByIdAndUserId(id,currentUser.id()).isEmpty())throw new ResourceNotFoundException("El cliente indicado no existe");} private void validateItems(List<ProposalItemRequest> r){r.forEach(i->{if(services.findByIdAndUserId(i.serviceId(),currentUser.id()).isEmpty())throw new ResourceNotFoundException("El servicio indicado no existe");});} private Proposal find(UUID id){return proposals.findByIdAndUserId(id,currentUser.id()).orElseThrow(()->new ResourceNotFoundException("No se encontró la propuesta"));} private static String clean(String v){return v.trim();} private static String optional(String v){if(v==null)return null;var x=v.trim();return x.isEmpty()?null:x;}
}
